#!/bin/sh
# Re-emit __this_module with the AOD311NK kernel's real struct module layout,
# then relink the .ko. Run inside the build container after `make M=... modules`.
#   usage: fix_this_module.sh <kmod-dir> <module-name>
# Device layout (from the router's own r8168_ioss.ko / ioss.ko):
#   sizeof(struct module) = 0x240, name @ 0x0c (60 bytes), init @ 0xf4, exit @ 0x200.
# The vanilla 5.4.265 headers give 0x200 / init 0xd0 / exit 0x1e0 (Qualcomm/Android
# adds fields), so the C definition generated by modpost must not be used.
set -eu
D=$1; M=$2
cd "$D"
MODC=$M.mod.c
[ -f "$MODC" ] || { echo "missing $MODC"; exit 1; }

# 1. drop the C definition of __this_module (from its line to the closing '};')
awk '
  /^__visible struct module __this_module/ {skip=1}
  skip && /^};/ {skip=0; next}
  !skip {print}
' "$MODC" > "$MODC.tmp"

# 2. append a raw, layout-exact definition
NAMELEN=$(printf "%s" "$M" | wc -c)
[ "$NAMELEN" -lt 60 ] || { echo "module name too long"; exit 1; }
cat >> "$MODC.tmp" <<EOF

/* AOD311NK struct module layout: size 0x240, name@0x0c, init@0xf4, exit@0x200 */
asm(
"	.section .gnu.linkonce.this_module,\"aw\"\n"
"	.balign 4\n"
"	.globl __this_module\n"
"	.type __this_module, %object\n"
"	.size __this_module, 0x240\n"
"__this_module:\n"
"	.space 0x0c\n"
"	.ascii \"$M\"\n"
"	.space 0xf4 - 0x0c - $NAMELEN\n"
"	.long init_module\n"
"	.space 0x200 - 0xf8\n"
"	.long cleanup_module\n"
"	.space 0x240 - 0x204\n"
"	.previous\n"
);
EOF
mv "$MODC.tmp" "$MODC"

# 3. recompile .mod.o and relink .ko with the exact commands kbuild used
MODCMD=$(sed -n 's/^cmd_\(.*\)\.mod\.o := //p' ".$M.mod.o.cmd")
KOCMD=$(sed -n 's/^cmd_\(.*\)\.ko := //p' ".$M.ko.cmd")
( cd "$KBUILD_TREE" && eval "$MODCMD" && eval "$KOCMD" )
echo "fixed $M.ko"
